import * as THREE from './vendor/three.module.js';
import {MAX_EXTENSION,SURFACE_SPAN,naturalForm,boundary,span,halfWidth,surfaceZ,contains,clamp,assisted,cycleForm,validForm,presetForm} from './nail-form.js';
const clone=v=>JSON.parse(JSON.stringify(v));
export function formGeometry(form){
 const points=boundary(form),w=form.naturalNailBounds.width,h=form.naturalNailBounds.height;
 if(!form.extensionLength){const shape=new THREE.Shape();points.forEach(([u,v],i)=>i?shape.lineTo((u-.5)*w,(.5-v)*h):shape.moveTo((u-.5)*w,(.5-v)*h));const g=new THREE.ShapeGeometry(shape);const p=g.attributes.position;for(let i=0;i<p.count;i++)g.attributes.uv.setXY(i,p.getX(i)/w+.5,1-(.5-p.getY(i)/h)/SURFACE_SPAN);return g;}
 const positions=[],uv=[],indices=[],rows=80,cols=20,low=-.0249,high=span(form)+.0099;
 for(let row=0;row<=rows;row++){const v=low+(high-low)*row/rows,half=halfWidth(form,v);for(let col=0;col<=cols;col++){const u=.5-half+2*half*col/cols;positions.push((u-.5)*w,(.5-v)*h,surfaceZ(form,u,v));uv.push(u,1-v/SURFACE_SPAN);if(row<rows&&col<cols){const a=row*(cols+1)+col,b=a+cols+1;indices.push(a,b,a+1,a+1,b,b+1);}}}
 const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geo.setIndex(indices);geo.computeVertexNormals();return geo;
}
export function createExtensionSystem(api){
 const {root,nails,specs,group,camera,renderer,hit,localPoint,selectNail,commitStroke,record,save,status,tone,charms,trim,frame}=api;
 let customMode=false,transition=null,selected=-1,active=false,drag=null,lastTap={id:-1,time:0},suggestion=-1;
 const controls=document.createElement('div');controls.id='sculpt-controls';controls.innerHTML='<button data-edge="left" aria-label="Sculpt left edge"></button><button data-edge="right" aria-label="Sculpt right edge"></button><button data-edge="tip" aria-label="Lengthen or shorten nail"></button><span id="sculpt-name"></span>';root.append(controls);controls.hidden=true;
 const guide=document.createElement('div');guide.id='extension-hint';guide.textContent='drag the tip · shape the edges · double-tap tip to turn the form';guide.hidden=true;root.append(guide);
 const gelMaterial=new THREE.ShaderMaterial({transparent:true,depthWrite:false,side:THREE.DoubleSide,uniforms:{length:{value:0},hover:{value:new THREE.Vector2()}},vertexShader:'varying vec2 tex;varying vec3 norm;void main(){tex=uv;norm=normalize(normalMatrix*normal);gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'uniform float length;uniform vec2 hover;varying vec2 tex;varying vec3 norm;void main(){float v=(1.-tex.y)*3.;float blend=smoothstep(.64,1.02,v);if(blend<.005)discard;vec3 light=normalize(vec3(-.35+hover.x*.16,.5+hover.y*.1,1.));float reflection=pow(max(0.,dot(normalize(norm),normalize(light+vec3(0.,0.,1.)))),32.);float apex=pow(max(0.,1.-abs(tex.x-.5)*2.),2.);vec3 color=mix(vec3(.86,.81,.72),vec3(.99,.98,.92),reflection*.6+apex*.15);gl_FragColor=vec4(color,blend*(.25+apex*.08+reflection*.13));}'});
 const ghostMat=new THREE.ShaderMaterial({transparent:true,depthWrite:false,side:THREE.DoubleSide,vertexShader:'varying vec2 tex;void main(){tex=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec2 tex;void main(){if((1.-tex.y)*3.<.95)discard;gl_FragColor=vec4(.88,.84,.74,.16);}'});
 const ghost=new THREE.Mesh(new THREE.BufferGeometry(),ghostMat);group.add(ghost);ghost.visible=false;
 const cutGhost=new THREE.Mesh(new THREE.BufferGeometry(),new THREE.ShaderMaterial({transparent:true,depthWrite:false,side:THREE.DoubleSide,uniforms:{cut:{value:1},width:{value:.5}},vertexShader:'varying vec2 tex;void main(){tex=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec2 tex;uniform float cut;uniform float width;void main(){float v=(1.-tex.y)*3.;float halfWidth=mix(.46,width*.5,clamp((v-.77)/max(.01,cut-.77),0.,1.));if(v<cut&&abs(tex.x-.5)<halfWidth)discard;gl_FragColor=vec4(.72,.36,.28,.16);}'} ));group.add(cutGhost);cutGhost.visible=false;
 const originalGeometries=nails.map(n=>n.mesh.geometry);
 function apply(id,form,quiet=false){const n=nails[id];n.form=clone(form);const old=n.mesh.geometry,geo=form.extensionLength?formGeometry(n.form):originalGeometries[id];n.mesh.geometry=geo;if(old!==geo&&old!==originalGeometries[id])old.dispose();n.mesh.material.uniforms.surfaceSpan.value=span(form);n.mesh.material.uniforms.extension.value=form.extensionLength;n.outline.visible=!form.extensionLength;
  if(!n.gel){n.gel=new THREE.Mesh(geo,gelMaterial.clone());n.gel.position.copy(n.mesh.position);n.gel.position.z=1.5;n.gel.rotation.copy(n.mesh.rotation);group.add(n.gel);n.rim=new THREE.LineLoop(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:'#ab927d',transparent:true,opacity:.65}));n.rim.position.copy(n.mesh.position);n.rim.position.z=1.8;n.rim.rotation.copy(n.mesh.rotation);group.add(n.rim);}
  n.gel.geometry=geo;n.gel.visible=!!form.extensionLength;n.gel.material.uniforms.length.value=form.extensionLength;n.gel.material.uniforms.hover.value=n.mesh.material.uniforms.hover.value;
  n.rim.geometry.dispose();n.rim.geometry=new THREE.BufferGeometry().setFromPoints(boundary(n.form).map(([u,v])=>new THREE.Vector3((u-.5)*specs[id][3],(.5-v)*specs[id][4],surfaceZ(n.form,u,v))));n.rim.visible=!!form.extensionLength;
  if(!quiet)charms()?.reflow();if(!quiet&&api.zoomed()&&!drag&&!transition)frame(id);
 }
 function restore(forms){nails.forEach((n,i)=>{const f=forms?.[i];apply(i,validForm(f)?{...f,naturalNailBounds:{width:specs[i][3],height:specs[i][4]}}:naturalForm(specs[i][3],specs[i][4]),true);});charms()?.reflow();}
 function before(id){return {form:clone(nails[id].form),actions:clone(nails[id].actions),charms:charms().state()};}
 function changed(id,prior){if(JSON.stringify(prior.form)===JSON.stringify(nails[id].form))return;const n=nails[id];trim(n,n.form);charms().trimTo(id,n.form);record({kind:'sculpt',id,before:prior});save();status();tone(n.form.extensionLength<prior.form.extensionLength?'snip':'settle');api.overview();suggest();api.selectionChanged?.();}
 function project(id,u,v){const n=nails[id],s=specs[id],p=new THREE.Vector3((u-.5)*s[3],(.5-v)*s[4],surfaceZ(n.form,u,v));n.mesh.localToWorld(p);p.project(camera);const r=renderer.domElement.getBoundingClientRect();return {x:(p.x+1)*r.width/2,y:(1-p.y)*r.height/2};}
 function controlsAt(id){const f=nails[id].form,L=f.extensionLength||.12,y=.99+L,v=.78+f.extensionLength*.5,half=halfWidth(f,v);return {left:{u:.5-half,v},tip:{u:.5,v:y},right:{u:.5+half,v}};}
 function select(id){selected=id;selectNail(id);controls.hidden=!active||!customMode;guide.hidden=!active;suggest();api.selectionChanged?.();}
 function suggest(){suggestion=-1;ghost.visible=false;if(!active||selected<0)return;const n=nails[selected],opposite=9-selected;if(n.form.extensionLength>.04&&Math.abs(n.form.extensionLength-nails[opposite].form.extensionLength)>.03){suggestion=opposite;showGhost(opposite,{...n.form,naturalNailBounds:nails[opposite].form.naturalNailBounds});}else if(!n.form.extensionLength)showGhost(selected,{...n.form,extensionLength:.12});}
 function showGhost(id,form){ghost.geometry.dispose();ghost.geometry=formGeometry(form);ghost.position.copy(nails[id].mesh.position);ghost.position.z=2.15;ghost.rotation.copy(nails[id].mesh.rotation);ghost.visible=true;}
 function ghostHit(e){if(!ghost.visible||suggestion<0||localPoint(e,nails[suggestion]).y/512<1)return false;const rect=renderer.domElement.getBoundingClientRect(),p=new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),ray=new THREE.Raycaster();ray.setFromCamera(p,camera);return ray.intersectObject(ghost,false).length>0;}
 function match(id){if(selected<0||id===selected)return;const prior=before(id),source=nails[selected].form;apply(id,{...source,extensionLength:clamp(source.extensionLength*source.naturalNailBounds.height/nails[id].form.naturalNailBounds.height,0,MAX_EXTENSION),naturalNailBounds:nails[id].form.naturalNailBounds});changed(id,prior);select(id);}
 function cycle(){if(selected<0)return;const prior=before(selected);apply(selected,cycleForm(nails[selected].form));changed(selected,prior);const label=controls.querySelector('span');label.textContent=nails[selected].form.shapeAssist;label.style.opacity='1';clearTimeout(cycle.timer);cycle.timer=setTimeout(()=>label.style.opacity='0',500);}
 function begin(e,edge){finishTransition();if(!customMode||selected<0||e.button>0)return;e.preventDefault();e.stopPropagation();commitStroke();const now=performance.now();if(edge==='tip'&&lastTap.id===selected&&now-lastTap.time<320){cycle();lastTap={id:-1,time:0};return;}lastTap=edge==='tip'?{id:selected,time:now}:{id:-1,time:0};const n=nails[selected],p=localPoint(e,n);drag={id:selected,edge,pointer:e.pointerId,start:{u:p.x/512,v:p.y/512},before:before(selected)};cutGhost.geometry.dispose();cutGhost.geometry=formGeometry(n.form);cutGhost.position.copy(n.mesh.position);cutGhost.position.z=3;cutGhost.rotation.copy(n.mesh.rotation);ghost.visible=false;e.target.setPointerCapture?.(e.pointerId);tone('stretch');}
 controls.querySelectorAll('button').forEach(b=>{b.addEventListener('pointerdown',e=>begin(e,b.dataset.edge));b.addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)||selected<0)return;e.preventDefault();const prior=before(selected),n=nails[selected],f=clone(n.form);if(b.dataset.edge==='tip')f.extensionLength=clamp(f.extensionLength+(e.key==='ArrowDown'?.04:-.04),0,MAX_EXTENSION);else f.tipWidth=clamp(f.tipWidth+(e.key==='ArrowRight'?.025:-.025),.015,.94);apply(selected,assisted(f));changed(selected,prior);});});
 renderer.domElement.addEventListener('pointerdown',e=>{if(!active||api.presenting()||e.button>0)return;e.preventDefault();e.stopImmediatePropagation();if(ghostHit(e)){match(suggestion);return;}const h=hit(e);if(!h)return;const id=h.object.userData.id;if(e.shiftKey&&selected>=0&&id!==selected)return;if(id!==selected){select(id);return;}const p=localPoint(e,nails[id]);if(customMode&&p.y/512>span(nails[id].form)-.25)begin(e,'tip');},true);
 renderer.domElement.addEventListener('dblclick',e=>{if(!active)return;e.preventDefault();e.stopImmediatePropagation();const h=hit(e);if(!h)return;const id=h.object.userData.id;if(e.shiftKey){match(id);return;}if(localPoint(e,nails[id]).y/512<span(nails[id].form)-.25)api.closeup(id);},true);
 window.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pointer)return;e.preventDefault();e.stopImmediatePropagation();const n=nails[drag.id],p=localPoint(e,n),u=p.x/512,v=p.y/512,f=clone(drag.before.form);
  if(drag.edge==='tip')f.extensionLength=clamp(f.extensionLength+v-drag.start.v,0,MAX_EXTENSION);
  else{f.tipWidth=clamp(drag.before.form.tipWidth+(u-drag.start.u)*(drag.edge==='left'?-2:2),.015,.94);f.sideTaper=clamp(drag.before.form.sideTaper+(drag.start.v-v)*.65,0,1);f.tipRoundness=clamp(drag.before.form.tipRoundness+(v-drag.start.v)*.75,0,1);}
  apply(drag.id,{...assisted(f),preset:'custom'});cutGhost.material.uniforms.cut.value=span(f);cutGhost.material.uniforms.width.value=f.tipWidth;cutGhost.visible=f.extensionLength<drag.before.form.extensionLength-.015||f.tipWidth<drag.before.form.tipWidth-.03;charms().previewTrim(drag.id,f);}, {capture:true,passive:false});
 function finish(commit=true){finishTransition();if(!drag)return;const d=drag;drag=null;cutGhost.visible=false;charms().previewTrim(-1);if(commit)changed(d.id,d.before);else apply(d.id,d.before.form);if(api.zoomed())frame(d.id);suggest();}
 window.addEventListener('pointerup',e=>{if(drag&&e.pointerId===drag.pointer){e.preventDefault();e.stopImmediatePropagation();finish();}},true);
 window.addEventListener('pointercancel',()=>finish(false),true);window.addEventListener('blur',()=>finish(false));
 function setActive(value){finish();active=value;controls.hidden=!value||selected<0||!customMode;guide.hidden=!value;root.classList.toggle('extending',value);suggest();}
 document.addEventListener('keydown',e=>{if(active&&e.key==='Escape'){finish(false);setActive(false);api.exit();e.stopImmediatePropagation();}},true);
 function finishTransition(){if(!transition)return;const t=transition;transition=null;for(const entry of t.entries){apply(entry.id,entry.target,true);trim(nails[entry.id],entry.target);charms().trimTo(entry.id,entry.target);}charms()?.reflow();record({kind:'reset',before:t.before});save();status();api.overview();tone('settle');suggest();api.selectionChanged?.();}
 function setPreset(name,length,all=false){finish();commitStroke();charms().cancel();const ids=all?nails.map(n=>n.id):selected>=0?[selected]:[];if(!ids.length){api.toast('Tap a nail first, or apply the shape to all.');return;}const prior={forms:nails.map(n=>clone(n.form)),nails:nails.map(n=>clone(n.actions)),charms:charms().state()};customMode=name==='custom';controls.hidden=!active||selected<0||!customMode;const entries=ids.map(id=>({id,from:clone(nails[id].form),target:presetForm(nails[id].form,name,length)}));if(entries.every(e=>JSON.stringify(e.from)===JSON.stringify(e.target)))return;transition={entries,before:prior,start:performance.now()};if(matchMedia('(prefers-reduced-motion: reduce)').matches)finishTransition();}
 function update(){if(transition){const p=Math.min(1,(performance.now()-transition.start)/280),e=p*p*(3-2*p);for(const entry of transition.entries){const f={...entry.target};for(const k of ['extensionLength','tipWidth','sideTaper','tipRoundness'])f[k]=entry.from[k]+(entry.target[k]-entry.from[k])*e;apply(entry.id,f,true);}charms()?.reflow();if(p===1)finishTransition();}for(const n of nails){if(n.gel){n.gel.scale.copy(n.mesh.scale);n.rim.scale.copy(n.mesh.scale);}}if(!active||selected<0)return;const anchors=controlsAt(selected);for(const b of controls.querySelectorAll('button')){const p=project(selected,anchors[b.dataset.edge].u,anchors[b.dataset.edge].v);b.style.left=p.x+'px';b.style.top=p.y+'px';}const tip=project(selected,.5,anchors.tip.v);const label=controls.querySelector('span');label.style.left=tip.x+'px';label.style.top=(tip.y+24)+'px';}
 return {setPreset,setCustom(v){customMode=v;controls.hidden=!active||selected<0||!v;},reset(){finish();selected=-1;customMode=false;controls.hidden=true;ghost.visible=false;cutGhost.visible=false;},selection:()=>selected>=0?{id:selected,name:nails[selected].name,form:clone(nails[selected].form)}:null,apply,restore,setActive,finish,update,state:()=>nails.map(n=>clone(n.form)),selected:()=>selected};
}
